// Alle Hotels bekommen denselben Typ-Marker wie die anderen Bestaende
// (Ferienwohnungen, Mietwagen, Fluege) — vereinfacht die Logik in results.js.
HOTELS.forEach((h) => { h.type = "hotel"; });

// ---- Hilfsfunktionen ----------------------------------------------------

function getHotelById(id) {
  return HOTELS.find((h) => h.id === id) || null;
}

function formatPrice(value) {
  return `${value.toLocaleString("de-DE")} €`;
}

/* Familienzimmer, wo ein Haus dafuer gebaut waere.
   ==================================================================
   Gemeldet am 02.10.2026: Im Dezember blieb am Ende ein einziges Haus
   im Vergleichsset uebrig. Der Nutzer dazu: "Dann ist ja nur ein Hotel
   da, das ist dann das Partnerhotel und dann funktioniert es ja nicht.
   Ich muss ja auch noch welche zum Vergleich geben."

   Gemessen war die Ursache nicht die Zahl der Haeuser, sondern ihre
   Belegung. Im Dezember sind 35 Hotels in einer warmen Region frei - in
   genau 8 davon passt eine Familie zu fuenft. Von 184 Hotels im Katalog
   haben nur 52 ueberhaupt ein Zimmer fuer fuenf, und das ist fuer einen
   Urlaubskatalog unrealistisch: Ein Strandhotel ohne Familienzimmer
   gibt es praktisch nicht.

   Deshalb bekommt jedes Haus, das dafuer gebaut waere, eines dazu.
   NICHT jedes: Ein Boutiquehotel in der Altstadt und ein Stadthotel
   haben keine Familienzimmer, und das soll auch so bleiben - sonst
   sieht der Katalog aus, als haette ihn niemand angesehen. Die
   Auswahl haengt an der Kategorie, die Ausstattung an der Hausnummer,
   damit nicht in allen Haeusern dasselbe steht.

   Preis: Der Aufschlag richtet sich nach dem groessten vorhandenen
   Zimmer plus einem Anteil des Nachtpreises. Ein Familienzimmer ist
   teurer als ein Doppelzimmer, aber guenstiger als zwei davon - sonst
   waere es keine Option, sondern eine Falle.
   ================================================================== */
(() => {
  // Diese Kategorien haben Familienzimmer, die anderen nicht
  const FUENF = ["familie", "strand", "apart", "budget", "luxus", "finca"];
  const SECHS = ["familie", "apart", "finca"];
  const AUSSTATTUNG = [
    ["Zwei verbundene Räume", "Platz für ein Zustellbett"],
    ["Separater Schlafbereich für die Kinder", "Zwei Waschbecken"],
    ["Schlafzimmer und Wohnraum getrennt", "Etagenbett"],
    ["Eigener Schlafraum für die Kinder", "Balkon mit Sitzgruppe"],
    ["Durchgangszimmer für die Kinder", "Extra Stauraum"],
  ];
  const nummer = (id) => {
    const n = parseInt(String(id).replace(/\D/g, ""), 10);
    return Number.isFinite(n) ? n : 0;
  };
  for (const h of HOTELS) {
    const zimmer = h.rooms || [];
    if (!zimmer.length) continue;
    const groesste = Math.max(...zimmer.map((r) => r.maxGuests || 0));
    if (groesste >= 5) continue;
    if (!FUENF.includes(h.category)) continue;
    // Ein Haus, dessen groesstes Zimmer fuer zwei reicht, hat keines fuer fuenf
    if (groesste < 3) continue;
    const n = nummer(h.id);
    const basis = zimmer.reduce((a, b) => ((b.maxGuests || 0) >= (a.maxGuests || 0) ? b : a), zimmer[0]);
    const aufschlag = Math.round((basis.priceDelta || 0) + (h.pricePerNight || 100) * 0.38);
    const merkmale = AUSSTATTUNG[n % AUSSTATTUNG.length];
    zimmer.push({
      name: "Familienzimmer", size: (basis.size || 24) + 12, maxGuests: 5,
      priceDelta: aufschlag, features: merkmale.slice(),
    });
    // Die Haeuser, die ausdruecklich auf Familien ausgerichtet sind, haben
    // auch etwas fuer sechs - eine Familie mit drei Kindern faellt sonst
    // ueberall heraus
    if (SECHS.includes(h.category) && n % 2 === 0) {
      zimmer.push({
        name: "Familiensuite", size: (basis.size || 24) + 26, maxGuests: 6,
        priceDelta: Math.round(aufschlag + (h.pricePerNight || 100) * 0.3),
        features: ["Zwei Schlafzimmer", "Wohnbereich mit Schlafsofa", "Zwei Bäder"],
      });
    }
  }
})();

/* Verpflegung nach festen Regeln ergaenzt (03.10.2026).
   ------------------------------------------------------------------
   Wunsch des Nutzers: Bei ueblichen Filtern sollen mindestens 40 Haeuser
   uebrig bleiben, damit das Vergleichsset nie aus zwei, drei Haeusern
   gebaut werden muss. Gemessen fehlte es vor allem an der Verpflegung:
   Halbpension hatten 143 von 218 Hotels, All Inclusive nur 56 - und nur
   in Strand- und Familienhotels.

   Ergaenzt wird, was ein solches Haus ueblicherweise anbietet, nicht
   alles ueberall:
   - Halbpension, wo es ein Restaurant gibt.
   - All Inclusive bei Resort-Kategorien an den Sonnenzielen. Kein All
     Inclusive in Staedten, in den Bergen oder im Norden - das gibt es
     dort auch sonst kaum.
   Die Aufpreise folgen den vorhandenen Haeusern derselben Art. */
/* Alle fuenf Verpflegungsstufen in jedem Hotel, Preis pro Person (03.10.2026).
   ------------------------------------------------------------------
   Gemeldet: "Halbpension" gewuenscht, und der Agent musste sie lockern,
   weil die Haeuser im Budget keine hatten - es gab sieben verschiedene
   Zusammenstellungen. Der Nutzer: "Bei solchen unwichtigen Sachen
   koennen wir es dem Agenten ja auch wirklich einfach machen, dass jedes
   Hotel dort die gleichen Verpflegungsstufen hat."

   Und: Verpflegung kostet pro Person, nicht pro Zimmer - Halbpension
   fuer vier kostet mehr als fuer zwei (Entscheidung vom selben Tag).

   Der Grundpreis bleibt, was er war (der Zimmerpreis); "ohne" kostet
   nichts. Die Aufschlaege pro Person und Nacht folgen dem Fruehstueck
   des Hauses, wo es eins gab, sonst zehn Prozent des Grundpreises -
   zwischen 8 und 30 Euro. Daraus: Halbpension das 2,2-fache,
   Vollpension das 3,2-fache, All Inclusive das 4,2-fache. Ferienwohnungen
   bleiben Selbstversorger. */
(function verpflegungVereinheitlichen() {
  for (const h of HOTELS) {
    const alt = (h.boards || []).find((b) => b.key === "fruehstueck")?.priceDelta;
    const fr = Math.min(30, Math.max(8, alt || Math.round((h.pricePerNight || 100) * 0.1)));
    h.boards = [
      { key: "ohne", priceDelta: 0 },
      { key: "fruehstueck", priceDelta: fr },
      { key: "halb", priceDelta: Math.round(fr * 2.2) },
      { key: "voll", priceDelta: Math.round(fr * 3.2) },
      { key: "ai", priceDelta: Math.round(fr * 4.2) },
    ];
  }
})();

/* ==================================================================
   Wellnessbereich und Hallenbad (03.11.2026)
   ------------------------------------------------------------------
   Der Massstab des Nutzers vom 03.11.2026: Egal welche Kombination
   jemand waehlt, es sollen mindestens 15 Haeuser uebrigbleiben, verteilt
   auf drei Preisstufen zu je fuenf. Der Grund: Dampfen die Filter die
   Menge auf vier Haeuser ein, ist die Auswahl schon durch die Filter
   entschieden, bevor das Partnerlabel ueberhaupt sichtbar wird - dann
   misst die Studie die Filter.

   Gemessen wurde danach, und es fehlte vor allem Ausstattung:

     Wellness in Wien 7 Haeuser, in Lissabon 5, in Barcelona 4
     Pool an der Ostsee 0, in Lappland 0, in Kyoto 0, in New York 1

   Beides ist nicht nur eine Luecke, sondern auch falsch: Ein
   Wellnessbereich gehoert in jedem groesseren Stadthotel zum Haus, und
   ein Ostseehotel ohne Schwimmbad ist die Ausnahme, nicht die Regel.

   Wie bei den Ferienwohnungen gilt: Die Bewertungen ziehen von selbst
   nach, weil sie aus den Aspekten erzeugt werden. Nur der
   Beschreibungstext braucht einen Satz, und den setzt dieser Durchlauf
   mit.

   Nicht angefasst: ein Pool in Lappland und auf Island. Wer dort danach
   filtert, bekommt die Rueckfrage des Agenten, dass die Vorgabe sehr
   einschraenkt - das ist die richtige Antwort, keine Luecke.
   ================================================================== */
(function hotelsAusstattung() {
  const ZIEL_SPA = 14;      // je Region mindestens, von 28 Haeusern
  const ZIEL_POOL = 14;
  // Wo ein Hallenbad zum Haus gehoert: kalte Regionen und Staedte
  const POOL_DAZU = ["ostsee", "kyoto", "newyork", "wien", "lissabon", "tirol", "suedtirol", "barcelona"];
  const satzSpa = "Zum Haus gehört ein Wellnessbereich mit Sauna und Ruheraum.";
  const satzPool = "Das Haus hat ein Hallenbad, das Gästen ganzjährig offensteht.";

  /* Die teureren Haeuser zuerst: Ein Wellnessbereich im billigsten
     Gaestehaus waere unglaubwuerdig, und die Preisstufen sollen sich
     durch den Durchlauf nicht verschieben. Bei gleichem Preis
     entscheidet die Kennung, damit die Auswahl bei jedem Laden dieselbe
     ist. */
  const reihenfolge = (liste) => liste.slice().sort((a, b) =>
    (b.pricePerNight || 0) - (a.pricePerNight || 0) || a.id.localeCompare(b.id));

  const ergaenzen = (ziele, merkmal, ziel, satz) => {
    for (const z of ziele) {
      const alle = HOTELS.filter((h) => h.ziel === z);
      const schon = alle.filter((h) => (h.amenities || []).includes(merkmal)).length;
      const offen = reihenfolge(alle.filter((h) => !(h.amenities || []).includes(merkmal)));
      for (const h of offen.slice(0, Math.max(0, ziel - schon))) {
        h.amenities = [...(h.amenities || []), merkmal];
        if (h.description && !h.description.includes(satz)) h.description += ` ${satz}`;
      }
    }
  };

  const alleZiele = [...new Set(HOTELS.map((h) => h.ziel))];
  ergaenzen(alleZiele, "spa", ZIEL_SPA, satzSpa);
  ergaenzen(POOL_DAZU, "pool", ZIEL_POOL, satzPool);
})();

function ratingLabel(rating) {
  if (rating >= 4.7) return "Außergewöhnlich";
  if (rating >= 4.4) return "Hervorragend";
  if (rating >= 4.0) return "Sehr gut";
  if (rating >= 3.5) return "Gut";
  return "Ordentlich";
}

function formatReviewDate(iso) {
  return new Date(iso).toLocaleDateString("de-DE", { month: "long", year: "numeric" });
}

if (typeof module !== "undefined" && module.exports) {
  module.exports = { HOTELS, AMENITY_LABELS, CATEGORY_LABELS, BOARD_LABELS };
}
